  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) client_p50_ms, approx_quantile(s.duration/1e6,0.5) server_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-seat-service' AND c.attr_span_kind='Client' GROUP BY ALL ORDER BY n DESC LIMIT 20",
          "claim": "Seat-service client POST to order-service takes ~2900ms p50 while order-service server span takes ~3.8ms; other seat client calls stay fast."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, attr_source, attr_destination, count(*) n, avg(value) v FROM abnormal_metrics_sum WHERE metric = 'hubble_drop_total' AND attr_source LIKE '%seat%' GROUP BY ALL",
          "claim": "Hubble shows no meaningful drops on seat connections; the wire is not the cause of the delay.",
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_source, attr_destination, count(*) n, avg(value) v FROM abnormal_metrics WHERE metric='hubble_http_request_duration_p95_seconds' AND (attr_source LIKE '%seat%' OR attr_destination LIKE '%seat%') GROUP BY ALL",
